/**
 * Manages client subscriptions for live streaming of trace events over Server-Sent Events (SSE). Clients register an
 * {@link SseEmitter} together with filter criteria (service, operation and client address patterns) and receive an SSE
 * event whenever new matching trace data arrives.
 */
@Component
public class TraceSubscriptionManager {

   private static final Logger log = LoggerFactory.getLogger(TraceSubscriptionManager.class);

   /** Storage service used to retrieve the spans associated with a trace. */
   private final SpanStorageService spanStorageService;

   /** Thread-safe list of currently registered subscriptions. */
   private final List<Subscription> subscriptions = new CopyOnWriteArrayList<>();

   /**
    * Create a new TraceSubscriptionManager.
    *
    * @param spanStorageService The storage service used to retrieve spans for a trace
    */
   public TraceSubscriptionManager(SpanStorageService spanStorageService) {
      this.spanStorageService = spanStorageService;
   }

   /**
    * Register an emitter to receive live trace events matching the provided filter criteria. A heartbeat SSE event is
    * sent immediately to confirm the connection.
    *
    * @param emitter       The emitter to register
    * @param serviceName   The service name pattern to filter on
    * @param operationName The operation name pattern to filter on
    * @param clientAddress The client address pattern to filter on
    */
   public void subscribe(SseEmitter emitter, String serviceName, String operationName, String clientAddress) {
      Subscription subscription = new Subscription(emitter, serviceName, operationName, clientAddress);
      subscriptions.add(subscription);

      emitter.onCompletion(() -> subscriptions.remove(subscription));
      emitter.onTimeout(() -> subscriptions.remove(subscription));
      emitter.onError(t -> subscriptions.remove(subscription));

      // Immediately send a heartbeat to confirm the subscription is live.
      try {
         emitter.send(SseEmitter.event().name("heartbeat").data("connected"));
      } catch (IOException e) {
         log.debug("Failed to send initial heartbeat, completing emitter: {}", e.getMessage());
         emitter.complete();
      }
   }

   /**
    * React to newly available trace data by notifying all matching subscribers.
    *
    * @param event The trace event describing the updated trace
    */
   @EventListener
   public void onTraceUpdated(TraceEvent event) {
      List<ReadableSpan> spans = spanStorageService.getSpansForTrace(event.traceId());
      if (spans == null || spans.isEmpty()) {
         // No spans to report, nothing to send.
         return;
      }

      TraceEvent fullEvent = SpanFilterUtil.extractTraceEvent(event.traceId(), spans);

      for (Subscription subscription : subscriptions) {
         if (SpanFilterUtil.matchesTraceEvent(fullEvent, subscription.serviceName(), subscription.operationName(),
               subscription.clientAddress())) {
            try {
               subscription.emitter().send(SseEmitter.event().name("trace").data(fullEvent.traceId()));
            } catch (IOException e) {
               log.debug("Failed to send trace event, completing emitter: {}", e.getMessage());
               subscription.emitter().complete();
            }
         }
      }
   }

